"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { ArrowDown, ArrowLeft, ArrowUp, Camera, Download, Eye, FileOutput, Plus, RefreshCw, RotateCcw, Save, Send, Sparkles, Trash2, Upload } from "lucide-react";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { Button } from "@/components/ui/button";
import { EditableReportPreview } from "@/components/reports/EditableReportPreview";
import { Input } from "@/components/ui/input";
import { API_URL } from "@/lib/constants";
import { getStoredToken } from "@/lib/auth";
import { ApiError } from "@/lib/api";
import { createEvidence } from "@/lib/api/evidences";
import { addCustomReportSection, addReportEvidence, applyReportAssistantProposal, applyReportEditorialPlan, createReportRevision, deleteCustomReportSection, deliverReportPublication, downloadReportPublication, generateReportAssistantProposal, generateReportEditorialPlan, generateReportPublication, generateReportSectionDraft, getAvailableReportEvidences, getReportAIGenerations, getReportEditor, getReportHtmlPreview, getReportPagePlan, getReportPublications, getReportRevisions, previewReportPdf, refreshReport, reorderReportSections, resetReportField, restoreReportRevision, updateReportDesign, updateReportEditorialConfig, updateReportEvidence, updateReportSection } from "@/lib/api/reports";
import type { AvailableReportEvidence, ReportAIAssistantProposal, ReportAIDraft, ReportAIEditorialPlan, ReportAIGenerationHistoryItem, ReportAILength, ReportAIStyle, ReportEditor, ReportEditorialConfig, ReportField, ReportLayoutVariant, ReportPageOverrideMode, ReportPagePlan, ReportPublication, ReportRevision, ReportSection, ReportTemplateKey, ReportTheme } from "@/types/report";
import { getReportAIMonthlyUsage } from "@/lib/api/reports";
import type { ReportAIUsageSummary } from "@/types/report";

const availability = { AVAILABLE: "Disponible", NO_DATA: "Sin datos", EVENT_LEVEL_ONLY: "Solo nivel evento", NOT_APPLICABLE: "No aplica" };
const layouts: Array<{ value: ReportLayoutVariant; label: string }> = [
  { value: "HERO_IMAGE_TEXT", label: "Imagen protagonista + texto" }, { value: "KPI_GRID", label: "Cuadrícula KPI" },
  { value: "TWO_COLUMN", label: "Dos columnas" }, { value: "METRIC_LIST", label: "Listado de métricas" },
  { value: "FEATURE_CHART", label: "Gráfico protagonista" }, { value: "PHOTO_GRID", label: "Galería fotográfica" },
  { value: "EDITORIAL", label: "Editorial" }, { value: "TEXT_IMAGE", label: "Texto + imagen" },
  { value: "BIG_NUMBERS", label: "Indicadores grandes" }
];
const templates: Array<{ value: ReportTemplateKey; label: string }> = [
  { value: "ENVIRONMENTAL_PREMIUM", label: "Ambiental premium" }, { value: "ENVIRONMENTAL_STORY", label: "Gestión ambiental premium" }, { value: "BIKE_ZONE", label: "Bike Zone" },
  { value: "OPERATIONS", label: "Operaciones" }, { value: "EXECUTIVE", label: "Ejecutivo" }, { value: "COMPLETE", label: "Completo" }
];
const defaultTheme: ReportTheme = { primary_color: "#12372A", secondary_color: "#2D6A4F", accent_color: "#95D5B2", background_color: "#F4F7F5", text_color: "#15231D", muted_color: "#61736A", cover_style: "DARK_OVERLAY", header_style: "MINIMAL", footer_style: "PAGE_NUMBER", show_page_numbers: true, show_event_name_in_footer: true };
const environmentalStoryTheme: Partial<ReportTheme> = { primary_color: "#204D20", secondary_color: "#34883A", accent_color: "#69B849", background_color: "#EFFBE8", text_color: "#173D1B", muted_color: "#58705B" };
const defaultVisual = { preset: "AUTO", icon_density: "MEDIUM", visual_density: "BALANCED", show_icons: true, show_trends: true, show_equivalences: true } as const;
const defaultEditorial: ReportEditorialConfig = { mode: "AUTO", cover_style: "FULL_PHOTO", cover_evidence_id: null, featured_kpi_ids: [], page_overrides: {}, chart_types: {}, visual_config: defaultVisual, section_visuals: {} };

export function ReportBuilder({ reportId }: { reportId: string }) {
  const suppressPreviewRefresh = useRef(false);
  const router = useRouter(); const [report, setReport] = useState<ReportEditor | null>(null); const [active, setActive] = useState<string>(); const [preview, setPreview] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState<string>(); const [notice, setNotice] = useState<string>(); const [custom, setCustom] = useState({ title: "", text: "" }); const [note, setNote] = useState(""); const [evidences, setEvidences] = useState<AvailableReportEvidence[]>([]); const [revisions, setRevisions] = useState<ReportRevision[]>([]); const [publications, setPublications] = useState<ReportPublication[]>([]); const [pagePlan, setPagePlan] = useState<ReportPagePlan>(); const [previewHtml, setPreviewHtml] = useState(""); const [confirmGenerate, setConfirmGenerate] = useState(false); const [deleteTarget, setDeleteTarget] = useState<ReportSection>(); const [editorialPlan, setEditorialPlan] = useState<ReportAIEditorialPlan>(); const [directorOpen, setDirectorOpen] = useState(false); const [directorStyle, setDirectorStyle] = useState<ReportAIStyle>("EXECUTIVE"); const [rollbackRevisionId, setRollbackRevisionId] = useState<string>();
  const [assistantOpen, setAssistantOpen] = useState(false); const [assistantInstructions, setAssistantInstructions] = useState(""); const [assistantProposal, setAssistantProposal] = useState<ReportAIAssistantProposal>(); const [aiHistory, setAIHistory] = useState<ReportAIGenerationHistoryItem[]>([]);
  const load = useCallback(async () => { try { const data = await getReportEditor(reportId); setReport(data); setActive(value => value || data.sections[0]?.id); } catch (e) { setError(e instanceof Error ? e.message : "No se pudo abrir el reporte"); } }, [reportId]);
  useEffect(() => { void load(); }, [load]);
  const currentId = report?.id;
  const currentVersion = report?.edit_version;
  useEffect(() => { if (currentId) { void getAvailableReportEvidences(currentId).then(setEvidences); void getReportRevisions(currentId).then(setRevisions); void getReportPublications(currentId).then(setPublications); void getReportPagePlan(currentId).then(setPagePlan); if (suppressPreviewRefresh.current) { suppressPreviewRefresh.current = false; return; } const timer = window.setTimeout(() => void getReportHtmlPreview(currentId).then(setPreviewHtml).catch(() => setPreviewHtml("")), 350); return () => window.clearTimeout(timer); } }, [currentId, currentVersion]);
  async function act(fn: () => Promise<unknown>, success?: string) { setBusy(true); setError(undefined); setNotice(undefined); try { await fn(); await load(); if (currentId) setPublications(await getReportPublications(currentId)); if (success) setNotice(success); } catch (e) { setError(e instanceof Error ? e.message : "No se pudo guardar"); } finally { setBusy(false); } }
  if (!report) return <main className="grid min-h-screen place-items-center bg-slate-50"><p>{error || "Cargando constructor…"}</p></main>;
  const currentReport = report;
  const section = currentReport.sections.find(item => item.id === active);
  async function saveSection(next: ReportSection) {
    setBusy(true); setError(undefined); setNotice(undefined);
    const payload = (editVersion: number) => ({ title: next.title, is_enabled: next.is_enabled, layout_variant: next.layout_variant, content: next.content, edit_version: editVersion });
    try {
      try {
        await updateReportSection(currentReport.id, next.id, payload(currentReport.edit_version));
      } catch (cause) {
        if (!(cause instanceof ApiError) || cause.status !== 409) throw cause;
        const latest = await getReportEditor(currentReport.id);
        await updateReportSection(currentReport.id, next.id, payload(latest.edit_version));
      }
      await load();
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "No se pudo guardar la sección");
      throw cause;
    } finally {
      setBusy(false);
    }
  }
  async function openPdf(blobPromise: Promise<Blob>) { const popup = window.open("about:blank", "_blank"); if (popup) { popup.opener = null; popup.document.title = "Preparando PDF…"; popup.document.body.innerHTML = '<p style="font-family:Arial;padding:24px">Preparando vista previa PDF…</p>'; } setBusy(true); try { const blob = await blobPromise; const url = URL.createObjectURL(blob); if (popup) popup.location.replace(url); else { const link = document.createElement("a"); link.href = url; link.target = "_blank"; link.rel = "noopener noreferrer"; link.click(); } setTimeout(() => URL.revokeObjectURL(url), 300_000); } catch (e) { popup?.close(); setError(e instanceof Error ? e.message : "No se pudo abrir el PDF"); } finally { setBusy(false); } }
  async function generatePdf() { setConfirmGenerate(false); await act(async () => { await generateReportPublication(currentReport.id, `${currentReport.id}:${currentReport.edit_version}`); setPublications(await getReportPublications(currentReport.id)); }, "PDF generado correctamente. Ya puedes verlo, descargarlo o entregarlo al cliente."); }
  async function saveRevision() { await act(async () => { await createReportRevision(currentReport.id, note, currentReport.edit_version); setNote(""); }, "Revisión guardada correctamente."); }
  async function move(id: string, delta: number) { const ids = currentReport.sections.map(x => x.id); const index = ids.indexOf(id); const target = index + delta; if (target < 0 || target >= ids.length) return; [ids[index], ids[target]] = [ids[target], ids[index]]; await act(() => reorderReportSections(currentReport.id, ids, currentReport.edit_version)); }
  async function removeSection(item: ReportSection) { setDeleteTarget(undefined); setActive(currentReport.sections.find(section => section.id !== item.id)?.id); await act(() => deleteCustomReportSection(currentReport.id, item.id, currentReport.edit_version)); }
  async function saveEditorial(patch: Partial<ReportEditorialConfig>, versionOffset = 0) { const config = { ...defaultEditorial, ...currentReport.editorial_config, ...patch } as ReportEditorialConfig; await updateReportEditorialConfig(currentReport.id, currentReport.edit_version + versionOffset, config); }
  async function selectCoverEvidence(evidenceId: string | null) { await act(async () => { const existing = currentReport.evidences.find(item => item.evidence_id === evidenceId); if (evidenceId && !existing) await addReportEvidence(currentReport.id, evidenceId, currentReport.edit_version); await saveEditorial({ cover_evidence_id: evidenceId }, evidenceId && !existing ? 1 : 0); }); }
  async function assignEvidence(evidenceId: string, sectionId: string) { await act(async () => { const existing = currentReport.evidences.find(item => item.evidence_id === evidenceId); if (existing) await updateReportEvidence(currentReport.id, existing.id, currentReport.edit_version, sectionId, existing.caption); else await addReportEvidence(currentReport.id, evidenceId, currentReport.edit_version, sectionId); }); }
  async function uploadEvidence(file: File, description: string, target: ReportSection) { await act(async () => { const form = new FormData(); form.append("event_id", currentReport.event_id); if (currentReport.scope === "SHOW" && currentReport.session_id) form.append("session_id", currentReport.session_id); form.append("description", description || `Fotografía para ${target.title}`); form.append("file", file); const evidence = await createEvidence(form); await addReportEvidence(currentReport.id, evidence.id, currentReport.edit_version, target.section_type === "COVER" ? undefined : target.id, description || evidence.description || undefined); if (target.section_type === "COVER") await saveEditorial({ cover_evidence_id: evidence.id }, 1); }, "Fotografía subida y asignada a la sección."); }
  async function setPageMode(sectionKey: string, mode: ReportPageOverrideMode, groupWith?: string | null) { const overrides = { ...(currentReport.editorial_config?.page_overrides || {}) }; if (mode === "AUTO") delete overrides[sectionKey]; else overrides[sectionKey] = { mode, group_with: mode === "GROUP_WITH" ? groupWith || null : null }; await act(() => saveEditorial({ page_overrides: overrides }), mode === "OWN_PAGE" ? "La sección ocupará una página completa." : "Distribución de página actualizada."); }
  async function askEditorialDirector(forceRefresh = false) { setBusy(true); setError(undefined); try { setEditorialPlan(await generateReportEditorialPlan(currentReport.id, directorStyle, true, forceRefresh)); setDirectorOpen(true); } catch (cause) { setError(cause instanceof Error ? cause.message : "No fue posible optimizar el informe"); } finally { setBusy(false); } }
  async function applyEditorialDirector() { if (!editorialPlan) return; setBusy(true); setError(undefined); try { const result = await applyReportEditorialPlan(currentReport.id, editorialPlan.generation_id, currentReport.edit_version); setRollbackRevisionId(result.revision_id); setReport(result.report); setEditorialPlan(undefined); setDirectorOpen(false); setNotice("Optimización aplicada. Puedes deshacerla y volver al estado anterior."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "No fue posible aplicar la propuesta"); } finally { setBusy(false); } }
  async function undoEditorialDirector() { if (!rollbackRevisionId) return; await act(async () => { await restoreReportRevision(currentReport.id, rollbackRevisionId, currentReport.edit_version); setRollbackRevisionId(undefined); }, "Optimización deshecha. El informe volvió al estado anterior."); }
  async function askReportAssistant(forceRefresh = false) { setBusy(true); setError(undefined); try { setAssistantProposal(await generateReportAssistantProposal(currentReport.id, assistantInstructions, forceRefresh)); setAIHistory(await getReportAIGenerations(currentReport.id)); } catch (cause) { setError(cause instanceof Error ? cause.message : "No fue posible generar la propuesta"); } finally { setBusy(false); } }
  async function applyAssistant(sectionKeys: string[], applyPreset: boolean) { if (!assistantProposal) return; setBusy(true); setError(undefined); try { const result = await applyReportAssistantProposal(currentReport.id, assistantProposal.generation_id, currentReport.edit_version, sectionKeys, applyPreset); setRollbackRevisionId(result.revision_id); setReport(result.report); setAssistantProposal(undefined); setAssistantOpen(false); setNotice("Cambios seleccionados de la propuesta IA aplicados. Puedes restaurar la revisión anterior."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "No fue posible aplicar la propuesta"); } finally { setBusy(false); } }
  async function refreshProfessionalPreview(refreshHtml = true) { if (!refreshHtml) { suppressPreviewRefresh.current = true; await load(); return; } const [nextHtml] = await Promise.all([getReportHtmlPreview(currentReport.id), load()]); setPreviewHtml(nextHtml); }
  return <main className="min-h-screen bg-slate-100">
    <header className="sticky top-0 z-20 border-b bg-white/95 px-5 py-3 backdrop-blur"><div className="mx-auto flex max-w-[1500px] items-center justify-between gap-3"><div className="flex items-center gap-3"><Button variant="ghost" onClick={() => router.back()}><ArrowLeft className="h-4 w-4"/></Button><div><p className="text-xs font-bold uppercase tracking-widest text-emerald-600">{report.scope === "SHOW" ? "Reporte por show" : "Reporte de evento"}</p><h1 className="font-bold text-slate-950">{report.title}</h1></div></div><div className="flex flex-wrap gap-2"><Button disabled={busy} onClick={() => void askEditorialDirector()}><Sparkles className="h-4 w-4"/>{busy ? "Analizando…" : "Optimizar informe con IA"}</Button>{rollbackRevisionId ? <Button variant="secondary" disabled={busy} onClick={() => void undoEditorialDirector()}><RotateCcw className="h-4 w-4"/>Deshacer optimización IA</Button> : null}<Button variant="secondary" disabled={busy} onClick={() => void act(() => refreshReport(report.id, report.edit_version), "Datos automáticos actualizados.")}><RefreshCw className="h-4 w-4"/>Actualizar datos</Button><Button variant="secondary" onClick={() => setPreview(!preview)}><Eye className="h-4 w-4"/>Preview</Button><Button variant="secondary" disabled={busy} onClick={() => void openPdf(previewReportPdf(report.id))}><FileOutput className="h-4 w-4"/>Vista previa PDF</Button><Button disabled={busy} onClick={() => void saveRevision()}><Save className="h-4 w-4"/>{busy ? "Procesando…" : "Guardar revisión"}</Button><Button disabled={busy} onClick={() => setConfirmGenerate(true)}><FileOutput className="h-4 w-4"/>Generar PDF</Button></div></div></header>
    {directorOpen && editorialPlan ? <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/60 p-4"><div role="dialog" aria-modal="true" aria-labelledby="editorial-director-title" className="mx-auto my-6 max-w-5xl rounded-3xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-widest text-violet-700">Propuesta reversible</p><h2 id="editorial-director-title" className="mt-1 text-2xl font-bold">Dirección editorial con IA</h2><p className="mt-2 text-sm text-slate-600">Revisa el orden, diseño y distribución antes de aplicar. Se guardará automáticamente una revisión completa para poder volver atrás.</p></div><Button variant="ghost" onClick={() => setDirectorOpen(false)}>Cerrar</Button></div><div className="mt-5 flex flex-wrap items-end gap-3 rounded-xl bg-slate-50 p-4"><label className="text-sm font-semibold">Enfoque<select className="ml-2 h-9 rounded-lg border bg-white px-3 font-normal" value={directorStyle} onChange={e => setDirectorStyle(e.target.value as ReportAIStyle)}><option value="EXECUTIVE">Ejecutivo</option><option value="TECHNICAL">Técnico</option><option value="COMMERCIAL">Comercial</option><option value="BRIEF">Breve</option></select></label><Button variant="secondary" disabled={busy} onClick={() => void askEditorialDirector(true)}><RefreshCw className="h-4 w-4"/>Generar otra propuesta</Button><span className="ml-auto text-xs text-slate-500">Modelo: {editorialPlan.effective_model || editorialPlan.model}</span></div><p className="mt-5 rounded-xl border border-violet-100 bg-violet-50 p-4 text-sm text-slate-700">{editorialPlan.overall_rationale}</p><div className="mt-5 overflow-hidden rounded-xl border"><table className="w-full text-left text-sm"><thead className="bg-slate-100"><tr><th className="p-3">Orden</th><th className="p-3">Sección</th><th className="p-3">Diseño actual</th><th className="p-3">Propuesta</th><th className="p-3">Página</th></tr></thead><tbody>{editorialPlan.section_order.map((key, index) => { const proposed = editorialPlan.sections.find(item => item.section_key === key); const current = report.sections.find(item => item.section_key === key); return <tr className="border-t align-top" key={key}><td className="p-3 font-bold">{index + 1}</td><td className="p-3"><b>{proposed?.title_suggestion || current?.title || key}</b><span className="mt-1 block text-xs text-slate-500">{proposed?.rationale}</span>{proposed?.generated_text ? <span className="mt-1 block text-xs font-medium text-violet-700">Incluye mejora de texto</span> : null}</td><td className="p-3 text-slate-500">{current?.layout_variant}</td><td className="p-3 font-semibold text-emerald-700">{proposed?.layout_variant}</td><td className="p-3">{proposed?.page_mode}</td></tr>; })}</tbody></table></div>{editorialPlan.warnings.length ? <ul className="mt-4 list-disc rounded-xl bg-amber-50 p-4 pl-9 text-sm text-amber-900">{editorialPlan.warnings.map((warning, index) => <li key={index}>{warning}</li>)}</ul> : null}<div className="mt-6 flex justify-end gap-2"><Button variant="secondary" onClick={() => { setDirectorOpen(false); setEditorialPlan(undefined); }}>Descartar propuesta</Button><Button disabled={busy} onClick={() => void applyEditorialDirector()}><Sparkles className="h-4 w-4"/>Aplicar propuesta reversible</Button></div></div></div> : null}
    {confirmGenerate ? <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4"><div role="dialog" aria-modal="true" className="max-w-md rounded-2xl bg-white p-6 shadow-2xl"><h2 className="text-xl font-bold">Generar versión PDF</h2><p className="mt-3 text-sm text-slate-600">Se generará una versión inmutable usando los datos actuales del reporte.</p><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" onClick={() => setConfirmGenerate(false)}>Cancelar</Button><Button onClick={() => void generatePdf()}>Generar versión</Button></div></div></div> : null}
    {deleteTarget ? <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/50 p-4"><div role="dialog" aria-modal="true" aria-labelledby="delete-section-title" className="max-w-md rounded-2xl bg-white p-6 shadow-2xl"><h2 id="delete-section-title" className="text-xl font-bold">Eliminar sección</h2><p className="mt-3 text-sm text-slate-600">Se eliminará definitivamente “{deleteTarget.title}”. Las evidencias originales se conservarán en el evento.</p><div className="mt-6 flex justify-end gap-2"><Button variant="secondary" onClick={() => setDeleteTarget(undefined)}>Cancelar</Button><Button className="bg-red-600 hover:bg-red-700" disabled={busy} onClick={() => void removeSection(deleteTarget)}>Eliminar</Button></div></div></div> : null}
    {error ? <div role="alert" className="mx-auto mt-4 max-w-[1500px] rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</div> : null}
    {notice ? <div role="status" className="mx-auto mt-4 flex max-w-[1500px] items-center justify-between rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm font-medium text-emerald-800"><span>{notice}</span><button type="button" className="ml-4 text-xs font-bold" onClick={() => setNotice(undefined)}>Cerrar</button></div> : null}
    <div className="mx-auto max-w-[1500px] px-5 pt-5"><DesignPanel report={report} busy={busy} unpublished={Boolean(publications[0] && report.updated_at && new Date(report.updated_at) > new Date(publications[0].generated_at))} onSave={(template, theme, editorial) => act(() => updateReportDesign(report.id, report.edit_version, template, theme, editorial))}/></div>
    <div data-testid="report-builder-three-panels" className="mx-auto grid max-w-[1800px] gap-4 p-5 xl:grid-cols-[minmax(250px,21%)_minmax(420px,38%)_minmax(390px,1fr)]">
      <aside className="space-y-4"><div className="rounded-2xl border bg-white p-3 shadow-sm"><div className="mb-3 flex items-center justify-between px-2"><strong>Secciones</strong><span className="text-xs text-slate-500">v{report.edit_version}</span></div>{report.sections.map((item, index) => <div key={item.id} className={`mb-2 rounded-xl border p-3 ${active === item.id ? "border-emerald-400 bg-emerald-50" : "border-slate-200"}`}><button className="w-full text-left" onClick={() => setActive(item.id)}><span className="block font-semibold">{item.title}</span><span className="text-xs text-slate-500">{availability[item.source_metadata.availability] || item.source_metadata.availability}</span></button><div className="mt-2 flex items-center gap-1"><input aria-label={`Mostrar ${item.title}`} type="checkbox" checked={item.is_enabled} onChange={() => void saveSection({ ...item, is_enabled: !item.is_enabled })}/><span className="mr-auto text-xs">Visible</span><Button size="sm" variant="ghost" disabled={!index} onClick={() => void move(item.id, -1)}><ArrowUp className="h-3 w-3"/></Button><Button size="sm" variant="ghost" disabled={index === report.sections.length - 1} onClick={() => void move(item.id, 1)}><ArrowDown className="h-3 w-3"/></Button></div></div>)}</div><div className="rounded-2xl border bg-white p-4"><strong>Contenido personalizado</strong><Input className="mt-3" placeholder="Título" value={custom.title} onChange={e => setCustom({ ...custom, title: e.target.value })}/><textarea className="mt-2 min-h-20 w-full rounded-lg border p-2 text-sm" placeholder="Contenido" value={custom.text} onChange={e => setCustom({ ...custom, text: e.target.value })}/><Button className="mt-2 w-full" variant="secondary" disabled={!custom.title || !custom.text} onClick={() => void act(async () => { await addCustomReportSection(report.id, custom.title, custom.text, report.edit_version); setCustom({ title: "", text: "" }); })}><Plus className="h-4 w-4"/>Agregar</Button></div><div className="rounded-2xl border bg-white p-4"><strong>Evidencias disponibles</strong>{evidences.length ? evidences.map(item => <div className="mt-2 flex items-center justify-between rounded-lg bg-slate-50 p-2 text-xs" key={item.id}><span className="line-clamp-1">{item.description || "Evidencia sin descripción"}</span><Button size="sm" disabled={item.selected || busy} onClick={() => void act(() => addReportEvidence(report.id, item.id, report.edit_version))}>{item.selected ? "Incluida" : "Incluir"}</Button></div>) : <p className="mt-2 text-xs text-slate-500">No hay evidencias para este alcance.</p>}</div><div className="rounded-2xl border bg-white p-4"><strong>Historial de revisiones</strong><Input className="mt-3" placeholder="Nota para la próxima revisión" value={note} onChange={e => setNote(e.target.value)}/>{revisions.map(item => <div className="mt-2 flex items-center justify-between text-xs" key={item.id}><span>v{item.revision_number} · {item.note || "Sin nota"}</span><Button size="sm" variant="ghost" onClick={() => void act(() => restoreReportRevision(report.id, item.id, report.edit_version))}>Restaurar</Button></div>)}</div><div className="rounded-2xl border bg-white p-4"><strong>Versiones PDF</strong>{publications.length ? publications.map(item => <div className="mt-3 rounded-xl border p-3 text-xs" key={item.id}><div className="flex items-center justify-between"><b>v{item.publication_number}</b><span>{item.status}</span></div><p className="mt-1 text-slate-500">{item.page_count} páginas · {(item.file_size / 1024).toFixed(0)} KB</p><div className="mt-2 flex gap-1"><Button size="sm" variant="ghost" onClick={() => void openPdf(downloadReportPublication(item.id, true))}><Eye className="h-3 w-3"/>Ver</Button><Button size="sm" variant="ghost" onClick={() => void openPdf(downloadReportPublication(item.id))}><Download className="h-3 w-3"/>Descargar</Button>{item.status === "GENERATED" ? <Button size="sm" onClick={() => void act(() => deliverReportPublication(item.id))}><Send className="h-3 w-3"/>Entregar</Button> : null}</div></div>) : <p className="mt-2 text-xs text-slate-500">Aún no hay publicaciones.</p>}</div></aside>
      <section>{section ? <SectionEditor section={section} report={report} busy={busy} evidences={evidences} onSave={saveSection} onDelete={() => setDeleteTarget(section)} onReset={(key) => act(() => resetReportField(report.id, section.id, key, report.edit_version))} onCoverStyle={(coverStyle) => act(() => saveEditorial({ cover_style: coverStyle }))} onSelectCover={selectCoverEvidence} onAssignEvidence={assignEvidence} onUploadEvidence={uploadEvidence} onPageMode={setPageMode}/> : null}</section>
      <section className={`${preview ? "block" : "hidden"} xl:block`}><EditableReportPreview reportId={report.id} html={previewHtml} plan={pagePlan} onSaved={refreshProfessionalPreview} onSelectSection={(key) => setActive(report.sections.find(item => item.section_key === key)?.id)}/></section>
    </div>
    {!assistantOpen ? <Button className="fixed bottom-6 right-6 z-30 shadow-xl" onClick={() => setAssistantOpen(true)}><Sparkles className="h-4 w-4"/>Asistente IA</Button> : <ReportAssistantPanel instructions={assistantInstructions} proposal={assistantProposal} history={aiHistory} busy={busy} onInstructions={setAssistantInstructions} onGenerate={askReportAssistant} onDiscard={() => setAssistantProposal(undefined)} onApply={applyAssistant} onClose={() => setAssistantOpen(false)}/>}
  </main>;
}

function DesignPanel({ report, busy, unpublished, onSave }: { report: ReportEditor; busy: boolean; unpublished: boolean; onSave: (template: ReportTemplateKey, theme: ReportTheme, editorial: ReportEditorialConfig) => Promise<unknown> }) {
  const [template, setTemplate] = useState<ReportTemplateKey>(report.template_key || "ENVIRONMENTAL_PREMIUM");
  const [theme, setTheme] = useState<ReportTheme>({ ...defaultTheme, ...report.theme });
  const [visual, setVisual] = useState({ ...defaultVisual, ...report.editorial_config?.visual_config });
  useEffect(() => { setTemplate(report.template_key || "ENVIRONMENTAL_PREMIUM"); setTheme({ ...defaultTheme, ...report.theme }); setVisual({ ...defaultVisual, ...report.editorial_config?.visual_config }); }, [report.template_key, report.theme, report.editorial_config?.visual_config]);
  useEffect(() => { if (template === "ENVIRONMENTAL_STORY") setTheme(current => ({ ...current, ...environmentalStoryTheme })); }, [template]);
  const colors: Array<[keyof Pick<ReportTheme, "primary_color" | "secondary_color" | "accent_color" | "background_color" | "text_color" | "muted_color">, string]> = [["primary_color", "Principal"], ["secondary_color", "Secundario"], ["accent_color", "Acento"], ["background_color", "Fondo"], ["text_color", "Texto"], ["muted_color", "Texto suave"]];
  const editorial = (nextVisual = visual): ReportEditorialConfig => ({ ...defaultEditorial, ...report.editorial_config, visual_config: nextVisual });
  return <div className="rounded-2xl border bg-white p-4 shadow-sm"><div className="flex flex-wrap items-end gap-3"><strong>Diseño editorial</strong>{unpublished ? <span className="mr-auto rounded-full bg-amber-100 px-2 py-1 text-xs font-semibold text-amber-800">Cambios sin publicar</span> : <span className="mr-auto"/>}<label className="text-xs font-semibold">Plantilla<select className="ml-2 h-9 rounded-lg border bg-white px-3 font-normal" value={template} onChange={event => setTemplate(event.target.value as ReportTemplateKey)}>{templates.map(item => <option key={item.value} value={item.value}>{item.label}</option>)}</select></label><label className="text-xs font-semibold">Estilo visual<select className="ml-2 h-9 rounded-lg border bg-white px-3 font-normal" value={visual.preset} onChange={event => setVisual(current => ({ ...current, preset: event.target.value as typeof current.preset }))}><option value="AUTO">Diseño base</option><option value="ECOEVENT_EDITORIAL">EcoEvent editorial</option><option value="EXECUTIVE">Ejecutivo</option><option value="ENVIRONMENTAL">Ambiental</option><option value="BIKE_ZONE">Bike Zone</option><option value="IMPACT">Impacto</option></select></label>{colors.map(([key, label]) => <label className="text-xs" key={key}>{label}<input className="ml-1 h-9 w-9 align-middle" aria-label={label} type="color" value={theme[key]} onChange={event => setTheme(current => ({ ...current, [key]: event.target.value.toUpperCase() }))}/></label>)}<Button variant="ghost" disabled={busy || visual.preset === "AUTO"} onClick={() => { const reset = { ...defaultVisual }; setVisual(reset); void onSave(template, theme, { ...editorial(reset), section_visuals: {} }); }}>Restablecer estilo visual</Button><Button variant="secondary" disabled={busy} onClick={() => void onSave(template, theme, editorial())}>Guardar diseño</Button></div></div>;
}

function SectionEditor({ section, report, busy, evidences, onSave, onDelete, onReset, onCoverStyle, onSelectCover, onAssignEvidence, onUploadEvidence, onPageMode }: { section: ReportSection; report: ReportEditor; busy: boolean; evidences: AvailableReportEvidence[]; onSave: (s: ReportSection) => Promise<void>; onDelete: () => void; onReset: (key: string) => Promise<unknown>; onCoverStyle: (style: ReportEditorialConfig["cover_style"]) => Promise<unknown>; onSelectCover: (id: string | null) => Promise<void>; onAssignEvidence: (evidenceId: string, sectionId: string) => Promise<void>; onUploadEvidence: (file: File, description: string, section: ReportSection) => Promise<void>; onPageMode: (sectionKey: string, mode: ReportPageOverrideMode, groupWith?: string | null) => Promise<void> }) {
  const [draft, setDraft] = useState(section);
  const [saveState, setSaveState] = useState<"idle" | "saving" | "saved" | "error">("idle");
  const [aiStyle, setAIStyle] = useState<ReportAIStyle>("EXECUTIVE");
  const [aiLength, setAILength] = useState<ReportAILength>("MEDIUM");
  const [aiCandidate, setAICandidate] = useState<ReportAIDraft>();
  const [aiBusy, setAIBusy] = useState(false);
  const [aiError, setAIError] = useState<string>();
  const [photo, setPhoto] = useState<File>();
  const [photoDescription, setPhotoDescription] = useState("");
  useEffect(() => setDraft(section), [section]);
  useEffect(() => { setAICandidate(undefined); setAIError(undefined); }, [section.id]);
  useEffect(() => {
    if (busy || JSON.stringify(draft) === JSON.stringify(section)) return;
    setSaveState("idle");
    const timer = window.setTimeout(() => {
      setSaveState("saving");
      void onSave(draft).then(() => setSaveState("saved")).catch(() => setSaveState("error"));
    }, 800);
    return () => window.clearTimeout(timer);
  }, [busy, draft, onSave, section]);
  function fieldChange(key: string, value: string) { setDraft(current => ({ ...current, content: { ...current.content, fields: current.content.fields.map(field => field.key === key ? { ...field, value, is_overridden: String(field.auto_value ?? "") !== value } : field) } })); }
  async function askAI(operation: "GENERATE" | "IMPROVE" | "REGENERATE") {
    setAIBusy(true); setAIError(undefined);
    try { setAICandidate(await generateReportSectionDraft(report.id, section.id, { operation, style: aiStyle, length: aiLength, current_text: draft.content.text || null })); }
    catch (cause) { setAIError(cause instanceof Error ? cause.message : "No fue posible generar el borrador"); }
    finally { setAIBusy(false); }
  }
  const assignedIds = new Set(report.evidences.filter(item => item.section_id === section.id).map(item => item.evidence_id));
  const pageOverride = report.editorial_config?.page_overrides?.[section.section_key];
  const pageMode = pageOverride?.mode || "AUTO";
  const groupTargets = report.sections.filter(item => item.id !== section.id && item.is_enabled && item.section_type !== "COVER");
  async function submitPhoto() { if (!photo) return; await onUploadEvidence(photo, photoDescription, section); setPhoto(undefined); setPhotoDescription(""); }
  return <div className="space-y-4">
    {section.is_custom ? <div className="flex justify-end"><Button aria-label={`Eliminar ${section.title}`} className="text-red-600 hover:text-red-700" size="sm" variant="secondary" disabled={busy} onClick={() => void onDelete()}><Trash2 className="h-4 w-4"/>Eliminar sección</Button></div> : null}
    <div className="rounded-3xl border bg-white p-6 shadow-sm">
      <div className="flex items-start justify-between gap-4"><div className="flex-1"><p className="text-xs font-bold uppercase tracking-widest text-emerald-600">{section.title}</p><Input aria-label="Título de la sección" className="mt-2 text-xl font-bold" value={draft.title} onChange={e => setDraft({ ...draft, title: e.target.value })}/></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs">{availability[section.source_metadata.availability]}</span></div>
      {section.section_type === "COVER" ? <fieldset className="mt-5"><legend className="text-sm font-semibold">Diseño de portada</legend><div className="mt-2 grid grid-cols-2 gap-2">{([['FULL_PHOTO','Foto completa'],['SIDE_PHOTO','Foto lateral'],['EDITORIAL','Editorial'],['MINIMAL_PREMIUM','Minimal premium']] as const).map(([value,label]) => <button type="button" key={value} aria-pressed={(report.editorial_config?.cover_style || 'FULL_PHOTO') === value} className={`rounded-xl border p-3 text-left text-sm ${(report.editorial_config?.cover_style || 'FULL_PHOTO') === value ? 'border-emerald-500 bg-emerald-50' : ''}`} onClick={() => void onCoverStyle(value)}>{label}</button>)}</div></fieldset> : <><fieldset className="mt-5"><legend className="text-sm font-semibold">Composición visual</legend><div data-testid="layout-thumbnail-selector" className="mt-2 grid grid-cols-2 gap-2 sm:grid-cols-3">{layouts.map(layout => <button type="button" key={layout.value} aria-pressed={draft.layout_variant === layout.value} className={`rounded-xl border p-2 text-left text-xs ${draft.layout_variant === layout.value ? 'border-emerald-500 bg-emerald-50' : ''}`} onClick={() => setDraft({ ...draft, layout_variant: layout.value })}><span aria-hidden className="mb-2 block h-10 rounded bg-gradient-to-br from-emerald-800 via-emerald-200 to-slate-100"/>{layout.label}</button>)}</div></fieldset><fieldset className="mt-5 rounded-2xl border border-emerald-100 bg-emerald-50/50 p-4"><legend className="px-2 text-sm font-semibold">Distribución en páginas</legend><label className="block text-xs font-semibold">Ubicación de esta sección<select aria-label="Distribución de la sección" className="mt-2 h-10 w-full rounded-lg border bg-white px-3 font-normal" value={pageMode} disabled={busy} onChange={event => { const mode = event.target.value as ReportPageOverrideMode; void onPageMode(section.section_key, mode, mode === "GROUP_WITH" ? pageOverride?.group_with || groupTargets[0]?.section_key : null); }}><option value="AUTO">Automática</option><option value="OWN_PAGE">Página completa</option><option value="NEW_PAGE">Comenzar página nueva</option><option value="GROUP_WITH" disabled={!groupTargets.length}>Agrupar con otra sección</option><option value="KEEP_WITH_NEXT">Mantener con la siguiente</option></select></label>{pageMode === "GROUP_WITH" ? <label className="mt-3 block text-xs font-semibold">Agrupar con<select aria-label="Sección de destino" className="mt-2 h-10 w-full rounded-lg border bg-white px-3 font-normal" value={pageOverride?.group_with || ""} disabled={busy} onChange={event => void onPageMode(section.section_key, "GROUP_WITH", event.target.value)}>{groupTargets.map(item => <option key={item.section_key} value={item.section_key}>{item.title}</option>)}</select></label> : null}<p className="mt-2 text-xs text-slate-600">Página completa reserva una hoja profesional para esta sección y ordena automáticamente sus textos, indicadores e imágenes.</p></fieldset></>}
      {section.source_metadata.availability === "EVENT_LEVEL_ONLY" ? <p className="mt-4 rounded-xl bg-amber-50 p-3 text-sm text-amber-800">Esta información existe para el evento completo, pero no está desagregada por show.</p> : null}
      {section.source_metadata.availability === "NO_DATA" ? <p className="mt-4 rounded-xl bg-slate-50 p-3 text-sm text-slate-600">Sin información automática. Puedes completar manualmente u ocultar la sección.</p> : null}
      {section.section_type === "ENVIRONMENTAL_IMPACT" ? <label className="mt-5 flex items-start gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm"><input className="mt-1" type="checkbox" checked={draft.content.show_traceability !== false} onChange={event => setDraft({ ...draft, content: { ...draft.content, show_traceability: event.target.checked } })}/><span><b>Incluir trazabilidad aprobada</b><span className="mt-1 block text-xs text-slate-600">Muestra en el PDF la acción, metodología y fuentes documentadas. Ocultarla no modifica los cálculos aprobados.</span></span></label> : null}
      <div className="mt-6 grid gap-4 sm:grid-cols-2">{draft.content.fields.map(field => <FieldEditor key={field.key} field={field} onChange={value => fieldChange(field.key, value)} onDescription={description => setDraft(current => ({ ...current, content: { ...current.content, fields: current.content.fields.map(item => item.key === field.key ? { ...item, description } : item) } }))} onToggle={() => setDraft(current => ({ ...current, content: { ...current.content, fields: current.content.fields.map(item => item.key === field.key ? { ...item, is_visible: item.is_visible === false } : item) } }))} onReset={() => void onReset(field.key)}/>)}</div>
      <label className="mt-5 block text-sm font-semibold">{section.section_type === "COVER" ? "Subtítulo" : "Texto del apartado"}{draft.content.text ? <span className="ml-2 rounded-full bg-slate-100 px-2 py-1 text-[10px] font-medium text-slate-600">{{ MANUAL: "Manual", AUTOFILLED: "Autocompletado", GENERATED: "Generado con IA", ENRICHED: "Enriquecido con IA" }[draft.content.text_origin || (draft.content.text === section.source_snapshot.text ? "AUTOFILLED" : "MANUAL")]}</span> : null}<textarea className="mt-2 min-h-28 w-full rounded-xl border p-3 font-normal" value={draft.content.text || ""} onChange={e => setDraft({ ...draft, content: { ...draft.content, text: e.target.value, text_origin: "MANUAL", ai_generation_id: null } })}/></label>
      {section.section_type !== "COVER" ? <ReportAIAssistant style={aiStyle} length={aiLength} candidate={aiCandidate} busy={aiBusy || busy} error={aiError} hasText={Boolean(draft.content.text)} onStyle={setAIStyle} onLength={setAILength} onGenerate={askAI} onDiscard={() => setAICandidate(undefined)} onAccept={() => { if (aiCandidate) setDraft(current => ({ ...current, content: { ...current.content, text: aiCandidate.generated_text, text_origin: current.content.text ? "ENRICHED" : "GENERATED", ai_generation_id: aiCandidate.generation_id } })); setAICandidate(undefined); }}/> : null}
      {section.section_type === "WASTE" || section.section_type === "CARBON" ? <ManualItemEditor items={draft.content.items} maxItems={section.section_type === "CARBON" ? 6 : 8} label={section.section_type === "WASTE" ? "material de reciclaje" : "ítem de huella de carbono"} onChange={items => setDraft(current => ({ ...current, content: { ...current.content, items } }))}/> : null}
      {draft.content.items.length ? <div className="mt-5 overflow-auto rounded-xl border"><table className="w-full text-sm"><tbody>{draft.content.items.map((item, i) => <tr key={i} className={`border-b ${item._is_visible === false ? "bg-slate-50 text-slate-400" : ""}`}><td className="w-12 p-3"><input type="checkbox" aria-label={`Mostrar fila ${i + 1}`} checked={item._is_visible !== false} onChange={() => setDraft(current => ({ ...current, content: { ...current.content, items: current.content.items.map((row, index) => index === i ? { ...row, _is_visible: row._is_visible === false } : row) } }))}/></td><td className="p-3 align-top">{String(item.label || item.name || "Ítem")} · {formatReportNumber(item.value ?? item.total_kg ?? item.total_kgco2e)} {String(item.unit || "")}</td><td className="w-1/2 p-2"><textarea aria-label={`Descripción de fila ${i + 1}`} className="min-h-16 w-full rounded-lg border p-2 text-xs" placeholder="Texto explicativo para el PDF" value={String(item.description || "")} onChange={event => setDraft(current => ({ ...current, content: { ...current.content, items: current.content.items.map((row, index) => index === i ? { ...row, description: event.target.value } : row) } }))}/></td></tr>)}</tbody></table></div> : null}
      <div className="mt-6 flex items-center justify-end gap-3"><span aria-live="polite" className={`text-xs ${saveState === "error" ? "text-red-600" : "text-slate-500"}`}>{saveState === "saving" ? "Guardando…" : saveState === "saved" ? "Guardado" : saveState === "error" ? "Error al guardar" : "Guardado automático activo"}</span><Button disabled={busy || saveState === "saving"} onClick={() => void onSave(draft)}>Guardar ahora</Button></div>
    </div>
    <div className="rounded-3xl border bg-white p-5 shadow-sm"><div className="flex items-center justify-between"><strong>{section.section_type === "COVER" ? "Fotografía principal" : "Fotografías de la sección"}</strong>{section.section_type === "COVER" && report.editorial_config?.cover_evidence_id ? <Button size="sm" variant="ghost" onClick={() => void onSelectCover(null)}>Quitar</Button> : null}</div><p className="mt-1 text-xs text-slate-500">Puedes subir una foto aquí o seleccionar una evidencia privada existente del {report.scope === 'SHOW' ? 'show' : 'evento'}.</p><div className="mt-4 rounded-2xl border border-dashed border-emerald-300 bg-emerald-50/60 p-4"><label className="flex cursor-pointer items-center gap-3 rounded-xl bg-white p-3 text-sm font-semibold shadow-sm"><Camera className="h-5 w-5 text-emerald-700"/><span className="flex-1 truncate">{photo?.name || "Seleccionar fotografía"}</span><input aria-label="Subir fotografía a la sección" className="sr-only" type="file" accept="image/jpeg,image/png,image/webp" onChange={event => setPhoto(event.target.files?.[0])}/><Upload className="h-4 w-4"/></label><Input className="mt-3" placeholder="Descripción de la fotografía" value={photoDescription} onChange={event => setPhotoDescription(event.target.value)}/><Button className="mt-3 w-full" type="button" disabled={!photo || busy} onClick={() => void submitPhoto()}><Upload className="h-4 w-4"/>{busy ? "Subiendo…" : "Subir y usar en esta sección"}</Button></div><div className="mt-4 grid grid-cols-2 gap-3">{evidences.map(item => <EvidenceChoice key={item.id} evidence={item} selected={section.section_type === "COVER" ? report.editorial_config?.cover_evidence_id === item.id : assignedIds.has(item.id)} onSelect={() => section.section_type === "COVER" ? onSelectCover(item.id) : onAssignEvidence(item.id, section.id)}/>)}</div>{!evidences.length ? <p className="mt-3 rounded-xl bg-slate-50 p-3 text-sm text-slate-500">Todavía no existen fotografías. Puedes cargar la primera desde este apartado.</p> : null}</div>
  </div>;
}
function ReportAIAssistant({ style, length, candidate, busy, error, hasText, onStyle, onLength, onGenerate, onDiscard, onAccept }: { style: ReportAIStyle; length: ReportAILength; candidate?: ReportAIDraft; busy: boolean; error?: string; hasText: boolean; onStyle: (value: ReportAIStyle) => void; onLength: (value: ReportAILength) => void; onGenerate: (operation: "GENERATE" | "IMPROVE" | "REGENERATE") => Promise<void>; onDiscard: () => void; onAccept: () => void }) {
  return <div className="mt-4 rounded-2xl border border-violet-200 bg-violet-50 p-4" aria-label="Asistente de IA para la sección"><div className="flex flex-wrap items-end gap-2"><div className="mr-auto"><strong className="flex items-center gap-2 text-sm"><Sparkles className="h-4 w-4 text-violet-700"/>Asistente de redacción</strong><p className="mt-1 text-xs text-slate-600">Genera un candidato con los datos incluidos. Nada cambia hasta que lo aceptes.</p></div><label className="text-xs font-semibold">Estilo<select aria-label="Estilo del borrador IA" className="ml-2 h-9 rounded-lg border bg-white px-2 font-normal" value={style} onChange={e => onStyle(e.target.value as ReportAIStyle)}><option value="EXECUTIVE">Ejecutivo</option><option value="TECHNICAL">Técnico</option><option value="COMMERCIAL">Comercial</option><option value="BRIEF">Breve</option></select></label><label className="text-xs font-semibold">Extensión<select aria-label="Extensión del borrador IA" className="ml-2 h-9 rounded-lg border bg-white px-2 font-normal" value={length} onChange={e => onLength(e.target.value as ReportAILength)}><option value="SHORT">Corta</option><option value="MEDIUM">Media</option><option value="LONG">Larga</option></select></label></div><div className="mt-3 flex flex-wrap gap-2"><Button type="button" size="sm" variant="secondary" disabled={busy} onClick={() => void onGenerate("GENERATE")}><Sparkles className="h-4 w-4"/>{busy ? "Generando…" : "Generar"}</Button><Button type="button" size="sm" variant="secondary" disabled={busy || !hasText} onClick={() => void onGenerate("IMPROVE")}>Mejorar texto</Button>{candidate ? <Button type="button" size="sm" variant="ghost" disabled={busy} onClick={() => void onGenerate("REGENERATE")}>Regenerar</Button> : null}</div>{error ? <p role="alert" className="mt-3 text-sm text-red-700">{error}</p> : null}{candidate ? <div className="mt-4 rounded-xl border bg-white p-4"><div className="flex items-center justify-between gap-3"><strong className="text-sm">Borrador sugerido</strong><span className="text-xs text-slate-500">{candidate.cached ? "Resultado reutilizado" : "Nueva generación"}</span></div>{candidate.title_suggestion ? <p className="mt-2 text-sm font-semibold">{candidate.title_suggestion}</p> : null}<p className="mt-2 whitespace-pre-wrap text-sm text-slate-700">{candidate.generated_text}</p>{candidate.warnings.length ? <ul className="mt-3 list-disc pl-5 text-xs text-amber-800">{candidate.warnings.map((warning, index) => <li key={index}>{warning}</li>)}</ul> : null}<div className="mt-4 flex justify-end gap-2"><Button type="button" size="sm" variant="ghost" onClick={onDiscard}>Descartar</Button><Button type="button" size="sm" onClick={onAccept}>Aceptar borrador</Button></div></div> : null}</div>;
}

function EvidenceChoice({ evidence, selected, onSelect }: { evidence: AvailableReportEvidence; selected: boolean; onSelect: () => Promise<void> }) { const [url, setUrl] = useState(""); useEffect(() => { let objectUrl = ""; void fetch(`${API_URL.replace(/\/api\/v\d+$/, "")}${evidence.preview_url}`, { headers: { Authorization: `Bearer ${getStoredToken() || ""}` } }).then(response => response.ok ? response.blob() : Promise.reject()).then(blob => { objectUrl = URL.createObjectURL(blob); setUrl(objectUrl); }).catch(() => undefined); return () => { if (objectUrl) URL.revokeObjectURL(objectUrl); }; }, [evidence.id, evidence.preview_url]); return <button type="button" aria-pressed={selected} onClick={() => void onSelect()} className={`overflow-hidden rounded-xl border text-left focus-visible:outline focus-visible:outline-2 focus-visible:outline-emerald-600 ${selected ? "border-emerald-500 ring-2 ring-emerald-200" : "border-slate-200"}`}>{url ? <Image unoptimized width={500} height={320} src={url} alt={evidence.description || "Evidencia del evento"} className="h-28 w-full object-cover"/> : <div className="h-28 animate-pulse bg-slate-200"/>}<span className="block p-2 text-xs"><b>{selected ? "Seleccionada" : "Seleccionar"}</b><span className="mt-1 block line-clamp-2 text-slate-500">{evidence.description || "Sin descripción"}</span>{evidence.taken_at ? <span className="mt-1 block text-slate-400">{new Intl.DateTimeFormat("es-CL", { timeZone: "America/Santiago", dateStyle: "medium" }).format(new Date(evidence.taken_at))}</span> : null}</span></button>; }
function FieldEditor({ field, onChange, onDescription, onToggle, onReset }: { field: ReportField; onChange: (v: string) => void; onDescription: (v: string) => void; onToggle: () => void; onReset: () => void }) {
  return <div className={`rounded-xl border p-4 text-sm ${field.is_visible === false ? "bg-slate-50 opacity-60" : ""}`}><div className="flex items-center justify-between gap-2"><label className="font-semibold" htmlFor={`field-${field.key}`}>{field.label}</label><label className="flex items-center gap-2 text-xs font-normal"><input type="checkbox" checked={field.is_visible !== false} onChange={onToggle}/>Incluir</label></div><Input id={`field-${field.key}`} className="mt-2" disabled={field.is_visible === false} value={String(field.value ?? "")} onChange={e => onChange(e.target.value)}/><textarea aria-label={`Descripción de ${field.label}`} className="mt-2 min-h-20 w-full rounded-lg border p-2 text-xs font-normal" disabled={field.is_visible === false} placeholder="Texto explicativo para el PDF" value={field.description || ""} onChange={event => onDescription(event.target.value)}/><div className="mt-2 flex items-center justify-between text-xs font-normal text-slate-500"><span>Automático: {formatReportNumber(field.auto_value)} {field.unit || ""}</span>{field.is_overridden ? <button className="flex items-center gap-1 font-semibold text-emerald-700" onClick={onReset} type="button"><RotateCcw className="h-3 w-3"/>Restablecer</button> : null}</div>{field.is_overridden ? <span className="mt-2 inline-block rounded-full bg-amber-100 px-2 py-1 text-xs text-amber-800">Editado manualmente</span> : null}</div>;
}

function formatReportNumber(value: unknown): string {
  if (value === null || value === undefined || value === "") return "Sin dato";
  const number = Number(value);
  if (!Number.isFinite(number)) return String(value);
  return new Intl.NumberFormat("es-CL", {
    minimumFractionDigits: 0,
    maximumFractionDigits: Math.abs(number) < 1 ? 5 : 2,
  }).format(number);
}
function ManualItemEditor({ items, label, maxItems, onChange }: { items: ReportSection["content"]["items"]; label: string; maxItems: number; onChange: (items: ReportSection["content"]["items"]) => void }) {
  const [name, setName] = useState(""); const [value, setValue] = useState(""); const [unit, setUnit] = useState(label.includes("carbono") ? "kgCO₂e" : "kg"); const [description, setDescription] = useState("");
  function add() { if (!name.trim() || items.length >= maxItems) return; onChange([...items, { label: name.trim(), value: value.trim() || null, unit: value.trim() ? unit.trim() : null, description: description.trim(), _manual: true, _is_visible: true }]); setName(""); setValue(""); setDescription(""); }
  function remove(index: number) { onChange(items.filter((_, itemIndex) => itemIndex !== index)); }
  return <div className="mt-5 rounded-xl border bg-slate-50 p-4"><div className="flex items-center justify-between"><strong className="text-sm">Agregar {label}</strong><span className="text-xs text-slate-500">{items.length}/{maxItems} por página</span></div><p className="mt-1 text-xs text-slate-500">El nombre es obligatorio. La cantidad y unidad son opcionales.</p><div className="mt-3 grid gap-2 sm:grid-cols-[1fr_110px_90px_auto]"><Input aria-label={`Nombre del ${label}`} placeholder="Nombre obligatorio" value={name} onChange={event => setName(event.target.value)}/><Input aria-label={`Cantidad del ${label}`} placeholder="Cantidad opcional" value={value} onChange={event => setValue(event.target.value)}/><Input aria-label={`Unidad del ${label}`} placeholder="Unidad" value={unit} onChange={event => setUnit(event.target.value)}/><Button type="button" disabled={!name.trim() || items.length >= maxItems} onClick={add}><Plus className="h-4 w-4"/>Agregar</Button></div><textarea aria-label={`Texto explicativo del ${label}`} className="mt-2 min-h-20 w-full rounded-lg border p-2 text-sm" placeholder="Texto explicativo que aparecerá bajo el indicador" value={description} onChange={event => setDescription(event.target.value)}/>{items.length ? <div className="mt-3 flex flex-wrap gap-2">{items.map((item, index) => <Button key={index} type="button" size="sm" variant="ghost" className="text-red-600" onClick={() => remove(index)}><Trash2 className="h-3 w-3"/>Quitar {String(item.label || item.name || "ítem")}</Button>)}</div> : null}</div>;
}
function PreviewSection({ section, evidences }: { section: ReportSection; evidences: AvailableReportEvidence[] }) { const hero = section.layout_variant === "HERO_IMAGE_TEXT"; const columns = section.layout_variant === "TWO_COLUMN" || section.layout_variant === "TEXT_IMAGE"; const big = section.layout_variant === "BIG_NUMBERS"; const photos = section.layout_variant === "PHOTO_GRID"; return <section data-layout={section.layout_variant} className={`border-b py-8 ${hero ? "rounded-3xl bg-slate-950 px-8 text-white" : ""}`}><div className={columns ? "grid gap-8 md:grid-cols-2" : ""}><div><p className="text-xs font-bold uppercase tracking-widest text-emerald-500">{layouts.find(x => x.value === section.layout_variant)?.label}</p><h3 className={`${hero ? "text-4xl" : "text-2xl"} mt-2 font-bold`}>{section.title}</h3>{section.content.text ? <p className={`mt-3 whitespace-pre-wrap ${hero ? "text-slate-300" : "text-slate-700"}`}>{section.content.text}</p> : null}</div><div className={`mt-4 grid gap-3 ${photos ? "grid-cols-2" : big ? "sm:grid-cols-2" : "sm:grid-cols-3"}`}>{section.content.fields.map(field => <div key={field.key} className={`${big ? "border-l-4 border-emerald-500 bg-emerald-50" : "bg-slate-50"} rounded-xl p-4 text-slate-950`}><p className="text-xs uppercase text-slate-500">{field.label}</p><p className={`${big ? "text-4xl" : "text-2xl"} mt-1 font-bold`}>{String(field.value ?? "—")} {field.unit}</p></div>)}</div></div>{photos || hero ? <PreviewEvidenceGallery evidences={hero ? evidences.slice(0, 1) : evidences}/> : null}</section>; }
function PreviewEvidenceGallery({ evidences }: { evidences: AvailableReportEvidence[] }) { const [urls, setUrls] = useState<Record<string, string>>({}); useEffect(() => { let disposed = false; const created: string[] = []; void Promise.all(evidences.map(async item => { const response = await fetch(`${API_URL.replace(/\/api\/v\d+$/, "")}${item.preview_url}`, { headers: { Authorization: `Bearer ${getStoredToken() || ""}` } }); if (!response.ok) return; const url = URL.createObjectURL(await response.blob()); created.push(url); if (!disposed) setUrls(current => ({ ...current, [item.id]: url })); })).catch(() => undefined); return () => { disposed = true; created.forEach(URL.revokeObjectURL); }; }, [evidences]); if (!evidences.length) return null; return <div className="mt-6 grid grid-cols-2 gap-3">{evidences.map((item, index) => urls[item.id] ? <figure className={index === 0 ? "col-span-2" : ""} key={item.id}><Image unoptimized width={1200} height={700} src={urls[item.id]} alt={item.description || "Evidencia del evento"} className="h-64 w-full rounded-2xl object-cover"/><figcaption className="mt-1 text-xs text-slate-500">{item.description}</figcaption></figure> : <div className="h-40 animate-pulse rounded-2xl bg-slate-200" key={item.id}/>)}</div>; }

function LegacyReportAssistantPanel({ instructions, proposal, history, busy, onInstructions, onGenerate, onDiscard, onApply, onClose }: { instructions: string; proposal?: ReportAIAssistantProposal; history: ReportAIGenerationHistoryItem[]; busy: boolean; onInstructions: (value: string) => void; onGenerate: (force: boolean) => Promise<void>; onDiscard: () => void; onApply: (...args: never[]) => Promise<void>; onClose: () => void }) {
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/60 p-4"><aside aria-label="Asistente IA de reportes" className="ml-auto min-h-full w-full max-w-3xl rounded-3xl bg-white p-6 shadow-2xl"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-violet-700">OpenAI · propuesta reversible</p><h2 className="text-2xl font-bold">Asistente IA</h2><p className="mt-1 text-sm text-slate-600">La IA trabaja sobre las secciones premium existentes. Nunca publica ni mueve posiciones manuales.</p></div><Button variant="ghost" onClick={onClose}>Cerrar</Button></div><label className="mt-6 block text-sm font-semibold">Describe el reporte que quieres generar<textarea className="mt-2 min-h-32 w-full rounded-xl border p-3 font-normal" placeholder="Crea un informe ejecutivo ambiental. Prioriza residuos e impacto. Compara los shows. Máximo 10 páginas." value={instructions} onChange={event => onInstructions(event.target.value)}/></label><div className="mt-3 flex gap-2"><Button disabled={busy || instructions.trim().length < 10} onClick={() => void onGenerate(false)}><Sparkles className="h-4 w-4"/>{busy ? "Generando…" : "Generar propuesta"}</Button>{proposal ? <Button variant="secondary" disabled={busy} title="Generará una nueva llamada al proveedor" onClick={() => void onGenerate(true)}><RefreshCw className="h-4 w-4"/>Regenerar (nueva generación)</Button> : null}</div>{proposal ? <div className="mt-6 space-y-5"><div className="rounded-2xl border border-violet-200 bg-violet-50 p-4"><div className="flex flex-wrap justify-between gap-2"><strong>Propuesta estructurada</strong><span className="text-xs">{proposal.effective_model || proposal.model} · {proposal.input_tokens} entrada / {proposal.output_tokens} salida · {proposal.actual_cost_usd == null ? "Costo no configurado" : `US$${proposal.actual_cost_usd.toFixed(4)}`}</span></div><p className="mt-2 text-sm">{proposal.rationale}</p><p className="mt-2 text-xs">Preset: <b>{proposal.recommended_preset}</b> · páginas estimadas: <b>{proposal.estimated_pages}</b></p></div><div><h3 className="font-bold">Cambios respecto del estado actual</h3>{proposal.diff.length ? <div className="mt-2 overflow-auto rounded-xl border"><table className="w-full text-sm"><thead className="bg-slate-50"><tr><th className="p-2 text-left">Elemento</th><th className="p-2 text-left">Actual</th><th className="p-2 text-left">Propuesto</th></tr></thead><tbody>{proposal.diff.map((item, index) => <tr className="border-t" key={`${item.type}-${item.key}-${index}`}><td className="p-2">{item.key} · {item.type}</td><td className="p-2 text-slate-500">{String(item.current ?? "—")}</td><td className="p-2 font-semibold text-emerald-700">{String(item.proposed ?? "—")}</td></tr>)}</tbody></table></div> : <p className="mt-2 text-sm text-slate-500">La propuesta conserva la configuración actual.</p>}</div><div><h3 className="font-bold">Secciones</h3><div className="mt-2 grid gap-2 sm:grid-cols-2">{proposal.sections.sort((a,b) => a.order-b.order).map(item => <div className="rounded-xl border p-3 text-sm" key={item.section_key}><b>{item.order + 1}. {item.section_key}</b><span className={`ml-2 rounded-full px-2 py-1 text-xs ${item.visible ? "bg-emerald-100 text-emerald-800" : "bg-slate-100"}`}>{item.visible ? "Visible" : "Oculta"}</span><p className="mt-2 text-xs text-slate-500">Variante certificada: {item.premium_variant} · énfasis {item.emphasis}</p></div>)}</div></div>{proposal.key_findings.length ? <div><h3 className="font-bold">Hallazgos</h3><ul className="mt-2 list-disc pl-5 text-sm">{proposal.key_findings.map((item,index) => <li key={index}>{item.text}</li>)}</ul></div> : null}{proposal.recommendations.length ? <div><h3 className="font-bold">Recomendaciones generadas por IA</h3><ul className="mt-2 space-y-2 text-sm">{proposal.recommendations.map((item,index) => <li className="rounded-xl bg-amber-50 p-3" key={index}><b>{item.title}</b><p>{item.description}</p></li>)}</ul></div> : null}{proposal.warnings.length ? <ul className="rounded-xl bg-amber-50 p-4 text-sm">{proposal.warnings.map((item,index) => <li key={index}>{item}</li>)}</ul> : null}<div className="flex justify-end gap-2"><Button variant="secondary" onClick={onDiscard}>Descartar</Button><Button disabled={busy} onClick={() => void onApply()}>Aplicar propuesta reversible</Button></div></div> : null}{history.length ? <details className="mt-8"><summary className="cursor-pointer font-semibold">Historial IA ({history.length})</summary><div className="mt-2 space-y-2 text-xs">{history.map(item => <div className="rounded-lg border p-2" key={item.id}>{new Date(item.created_at).toLocaleString("es-CL")} · {item.capability} · {item.effective_model || item.model} · {item.status}{item.applied ? " · aplicada" : ""}{item.actual_cost_usd == null ? "" : ` · US$${item.actual_cost_usd.toFixed(4)}`}</div>)}</div></details> : null}</aside></div>;
}

function ReportAssistantPanel({ instructions, proposal, history, busy, onInstructions, onGenerate, onDiscard, onApply, onClose }: { instructions: string; proposal?: ReportAIAssistantProposal; history: ReportAIGenerationHistoryItem[]; busy: boolean; onInstructions: (value: string) => void; onGenerate: (force: boolean) => Promise<void>; onDiscard: () => void; onApply: (sectionKeys: string[], applyPreset: boolean) => Promise<void>; onClose: () => void }) {
  const [selected, setSelected] = useState<string[]>([]);
  const [preset, setPreset] = useState(true);
  const [usage, setUsage] = useState<ReportAIUsageSummary>();
  useEffect(() => { setSelected(proposal?.sections.map(item => item.section_key) || []); setPreset(true); }, [proposal]);
  useEffect(() => { void getReportAIMonthlyUsage().then(setUsage).catch(() => setUsage(undefined)); }, [history.length, proposal?.generation_id]);
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/60 p-4"><aside aria-label="Asistente IA de reportes" className="ml-auto min-h-full w-full max-w-3xl rounded-3xl bg-white p-6 shadow-2xl">
    <div className="flex justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-violet-700">OpenAI · propuesta reversible</p><h2 className="text-2xl font-bold">Asistente IA</h2>{usage ? <p className="mt-1 text-xs text-slate-500">Consumo {usage.month}: US${usage.spent_usd.toFixed(4)} de US${usage.budget_usd.toFixed(2)} · saldo US${usage.remaining_usd.toFixed(4)}</p> : null}</div><Button variant="ghost" onClick={onClose}>Cerrar</Button></div>
    <label className="mt-6 block text-sm font-semibold">Describe el reporte<textarea className="mt-2 min-h-32 w-full rounded-xl border p-3 font-normal" value={instructions} onChange={event => onInstructions(event.target.value)}/></label>
    <div className="mt-3 flex gap-2"><Button disabled={busy || instructions.trim().length < 10} onClick={() => void onGenerate(false)}><Sparkles className="h-4 w-4"/>{busy ? "Generando…" : "Generar propuesta"}</Button>{proposal ? <Button variant="secondary" disabled={busy} onClick={() => void onGenerate(true)}><RefreshCw className="h-4 w-4"/>Regenerar</Button> : null}</div>
    {proposal ? <div className="mt-6 space-y-5"><div className="rounded-2xl border border-violet-200 bg-violet-50 p-4"><div className="flex justify-between gap-2"><strong>Propuesta estructurada</strong><span className="text-xs">{proposal.effective_model || proposal.model} · US${(proposal.actual_cost_usd || 0).toFixed(4)}</span></div><p className="mt-2 text-sm">{proposal.rationale}</p></div>
      <div><h3 className="font-bold">Selecciona qué secciones aplicar</h3><div className="mt-2 grid gap-2 sm:grid-cols-2">{[...proposal.sections].sort((a,b) => a.order-b.order).map(item => <label className="rounded-xl border p-3 text-sm" key={item.section_key}><input className="mr-2" type="checkbox" aria-label={`Aplicar ${item.section_key}`} checked={selected.includes(item.section_key)} onChange={() => setSelected(current => current.includes(item.section_key) ? current.filter(key => key !== item.section_key) : [...current, item.section_key])}/><b>{item.order + 1}. {item.section_key}</b><p className="mt-2 text-xs text-slate-500">{item.visible ? "Visible" : "Oculta"} · {item.premium_variant}</p></label>)}</div></div>
      <label className="block rounded-xl border p-3 text-sm"><input className="mr-2" type="checkbox" checked={preset} onChange={event => setPreset(event.target.checked)}/>Aplicar también el preset visual <b>{proposal.recommended_preset}</b></label>
      <div className="flex justify-end gap-2"><Button variant="secondary" onClick={onDiscard}>Descartar</Button><Button disabled={busy || (!selected.length && !preset)} onClick={() => void onApply(selected, preset)}>Aplicar seleccionados</Button></div></div> : null}
    {history.length ? <details className="mt-8"><summary className="cursor-pointer font-semibold">Historial IA ({history.length})</summary><div className="mt-2 space-y-2 text-xs">{history.map(item => <div className="rounded-lg border p-2" key={item.id}>{new Date(item.created_at).toLocaleString("es-CL")} · {item.status}{item.actual_cost_usd == null ? "" : ` · US$${item.actual_cost_usd.toFixed(4)}`}</div>)}</div></details> : null}
  </aside></div>;
}
